/* Global navigation feedback for real document navigations. */
(function () {
    // Inline the small loader GIF to avoid Render/static-path/phone cache 404s.
    const CHEETAH_GIF = 'data:image/gif;base64,';

    // Decode the runner during page idle time. Creating the image only inside
    // beforeunload is too late on slower phones and leaves a blank image box.
    const cheetahRunner = new Image(440, 192);
    cheetahRunner.className = 'gp-cheetah-runner';
    cheetahRunner.alt = '';
    cheetahRunner.setAttribute('aria-hidden', 'true');
    cheetahRunner.decoding = 'sync';
    cheetahRunner.fetchPriority = 'high';
    cheetahRunner.src = CHEETAH_GIF;
    let cheetahDecoded = false;
    const cheetahDecodeReady = typeof cheetahRunner.decode === 'function'
        ? cheetahRunner.decode().then(() => { cheetahDecoded = true; }).catch(() => {})
        : new Promise((resolve) => {
            cheetahRunner.onload = () => { cheetahDecoded = true; resolve(); };
            cheetahRunner.onerror = resolve;
        });
    let shown = false;
    let overlay = null;

    function ensureOverlay() {
        if (overlay) return overlay;
        overlay = document.createElement('div');
        overlay.id = 'gpPageNavigationLoader';
        overlay.className = 'gp-page-navigation-loader';
        overlay.setAttribute('role', 'status');
        overlay.setAttribute('aria-live', 'polite');
        overlay.innerHTML = `
            <div class="gp-loader-red-streak gp-loader-red-streak-top" aria-hidden="true"></div>
            <div class="gp-loader-red-streak gp-loader-red-streak-bottom" aria-hidden="true"></div>
            <div class="gp-page-loader-content">
                <div class="gp-page-loader-title"><span>OPENING</span> <b>PAGE</b></div>
                <div class="gp-page-loader-progress" role="progressbar" aria-label="Page loading" aria-valuetext="Loading">
                    <span></span>
                </div>
                <small class="gp-page-loader-caption">Preparing your workspace</small>
            </div>`;
        const content = overlay.querySelector('.gp-page-loader-content');
        if (content) content.insertBefore(cheetahRunner, content.firstChild);
        // Never expose an empty bordered placeholder while the first frame decodes.
        if (!cheetahDecoded) {
            cheetahRunner.style.visibility = 'hidden';
            cheetahDecodeReady.then(() => {
                if (overlay && overlay.isConnected) cheetahRunner.style.visibility = 'visible';
            });
        } else {
            cheetahRunner.style.visibility = 'visible';
        }
        return overlay;
    }

    function show() {
        if (shown) return;
        shown = true;
        const node = ensureOverlay();
        (document.body || document.documentElement).appendChild(node);
        requestAnimationFrame(() => node.classList.add('is-visible'));
    }

    function hide() {
        shown = false;
        if (!overlay) return;
        overlay.classList.remove('is-visible');
        overlay.remove();
        overlay = null;
    }

    // Show immediately for same-origin links so the mobile browser can paint
    // the already-decoded cheetah before it starts the next document request.
    document.addEventListener('click', (event) => {
        const link = event.target.closest && event.target.closest('a[href]');
        if (!link || link.hasAttribute('download')) return;
        if (link.target && link.target.toLowerCase() !== '_self') return;
        const href = link.getAttribute('href');
        if (!href || href.startsWith('#') || /^\s*javascript:/i.test(href)) return;
        let destination;
        try { destination = new URL(link.href, window.location.href); } catch (_) { return; }
        if (destination.origin !== window.location.origin || destination.href === window.location.href) return;
        show();
        const currentUrl = window.location.href;
        window.setTimeout(() => {
            if (document.visibilityState === 'visible' && window.location.href === currentUrl) hide();
        }, 1800);
    }, true);

    document.addEventListener('submit', (event) => {
        const form = event.target;
        if (!(form instanceof HTMLFormElement)) return;
        if (form.target && form.target.toLowerCase() !== '_self') return;
        show();
    }, true);

    // beforeunload remains the fallback for JS-driven redirects.
    window.addEventListener('beforeunload', show);
    window.addEventListener('pagehide', show);
    window.addEventListener('pageshow', hide);
    document.addEventListener('DOMContentLoaded', hide, { once: true });

    window.GPPageNavigation = { show, hide };
})();
